199	<body>
200	  <main>
201	    <h1 class="visually-hidden">Animated Circle</h1>
202	    <button type="button" class="no-transition" aria-label="Change circle color" aria-describedby="status hint">
203	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
204	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
205	      </svg>
206	      <span class="color-indicator" aria-hidden="true"></span>
207	    </button>
208	    <p class="status" id="status" role="status" aria-atomic="true" aria-live="polite">Blue</p>
209	    <p class="hint" id="hint"><span class="verb">Click</span> to cycle<span class="keys"> • <kbd>Shift</kbd> reverse • <kbd>↑↓←→</kbd> navigate • <kbd>Home</kbd>/<kbd>End</kbd> jump</span></p>
210	  </main>
211	  <script>
212	    const button = document.querySelector('button');
213	    const status = document.querySelector('.status');
214	    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
215	    const storageKey = 'circle-color';
216	
217	    // Safely retrieve saved color from localStorage, returning null if unavailable
218	    function loadColor() {
219	      try {
220	        return localStorage.getItem(storageKey);
221	      } catch {
222	        return null;
223	      }
224	    }
225	
226	    // Safely save color to localStorage, silently failing if unavailable
227	    function saveColor(color) {
228	      try {
229	        localStorage.setItem(storageKey, color);
230	      } catch {}
231	    }
232	
233	    const savedColor = loadColor();
234	    let index = colors.includes(savedColor) ? colors.indexOf(savedColor) : 0;
235	
236	    // Apply current color to button and update status display
237	    function applyColor() {
238	      const color = colors[index];
239	      if (color === 'blue') {
240	        delete button.dataset.color;
241	      } else {
242	        button.dataset.color = color;
243	      }
244	      status.textContent = color[0].toUpperCase() + color.slice(1);
245	    }
246	
247	    // Cycle color by step amount and trigger pulse animation
248	    function changeColor(step) {
249	      const next = (index + step + colors.length) % colors.length;
250	      // Home/End at the boundary shouldn't pulse or rewrite storage
251	      if (next === index) return;
252	      index = next;
253	      applyColor();
254	      saveColor(colors[index]);
255	
256	      // Haptic feedback for supported devices
257	      if (navigator.vibrate) navigator.vibrate(50);
258	
259	      button.classList.remove('color-changed');
260	      void button.offsetWidth;
261	      button.classList.add('color-changed');
262	    }
263	
264	    applyColor();
265	    // Double rAF ensures paint completes before enabling animations
266	    requestAnimationFrame(() => requestAnimationFrame(() => {
267	      button.classList.remove('no-transition');
268	    }));
269	
270	    // Update instructions to show "Tap" on touch devices or "Click" on hover-capable devices
271	    const hoverQuery = matchMedia('(hover: none)');
272	    const verbSpan = document.querySelector('.hint .verb');
273	    function updateVerb() {
274	      verbSpan.textContent = hoverQuery.matches ? 'Tap' : 'Click';
275	    }
276	    updateVerb();
277	    hoverQuery.addEventListener('change', updateVerb);
278	
279	    // Space and Enter activate through the native click, but keyboard-synthesized
280	    // clicks don't reliably carry shiftKey, so remember it from the key events
281	    let shiftHeld = false;
282	    const isActivationKey = (event) => event.key === 'Enter' || event.key === ' ';
283	    // Space clicks on keyup; Enter already clicked on keydown, so updating
284	    // shiftHeld on Enter's keyup would leak into the next mouse click
285	    button.addEventListener('keyup', (event) => {
286	      if (event.key === ' ') shiftHeld = event.shiftKey;
287	    });
288	    button.addEventListener('blur', () => {
289	      shiftHeld = false;
290	    });
291	
292	    const keySteps = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
293	    button.addEventListener('keydown', (event) => {
294	      if (isActivationKey(event)) {
295	        shiftHeld = event.shiftKey;
296	        // Holding Enter would otherwise fire a click on every repeat
297	        if (event.repeat && event.key === 'Enter') event.preventDefault();
298	        return;
299	      }
300	      if (event.altKey || event.ctrlKey || event.metaKey) return;
301	      if (event.key in keySteps) {
302	        event.preventDefault();
303	        changeColor(keySteps[event.key]);
304	      } else if (event.key === 'Home') {
305	        event.preventDefault();
306	        changeColor(-index);
307	      } else if (event.key === 'End') {
308	        event.preventDefault();
309	        changeColor(colors.length - 1 - index);
310	      }
311	    });
312	    button.addEventListener('click', (event) => {
313	      changeColor(event.shiftKey || shiftHeld ? -1 : 1);
314	      shiftHeld = false;
315	    });
316	    button.addEventListener('animationend', () => {
317	      button.classList.remove('color-changed');
318	    });
319	    // Sync color across tabs when storage changes
320	    addEventListener('storage', (event) => {
321	      // key is null when another tab calls localStorage.clear()
322	      if (event.key !== storageKey && event.key !== null) return;
323	      const newIndex = colors.indexOf(event.newValue);
324	      index = newIndex === -1 ? 0 : newIndex;
325	      applyColor();
326	    });
327	  </script>
328	</body>
