body {
  min-height: 100vh;
  min-height: 100dvh;
  display: grid;
  place-items: center;
  padding: 1rem;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, sans-serif;
}
main {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}
button {
  display: block;
  width: min(360px, 100%, 60vh);
  aspect-ratio: 1;
  border: 0;
  border-radius: 50%;
  background: none;
  color: var(--fg);
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  transition: color 0.4s ease;
  position: relative;
  min-height: 48px;
  min-width: 48px;
}
.color-indicator {
  position: absolute;
  bottom: 12%;
  right: 12%;
  width: 1rem;
  height: 1rem;
  border-radius: 50%;
  background: currentColor;
  border: 2px solid var(--bg);
  box-shadow: 0 2px 4px var(--shadow);
}
.no-transition,
.no-transition svg,
.no-transition .color-indicator {
  transition: none !important;
}
button:focus-visible {
  outline: 3px solid currentColor;
  /* Must clear the scaled-up circle (up to 9px) or the ring merges with it */
  outline-offset: 12px;
}
svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
  opacity: 0.85;
  --drop: drop-shadow(0 4px 12px var(--shadow));
  filter: var(--drop);
  transition: opacity 0.3s ease;
  backface-visibility: hidden;
  will-change: opacity, transform;
}
button:active svg,
button:focus-visible svg {
  opacity: 1;
}
@keyframes pulse {
  0% {
    filter: var(--drop) drop-shadow(0 0 16px currentColor);
  }
  100% {
    filter: var(--drop) drop-shadow(0 0 0 transparent);
  }
}
@media (hover: hover) {
  button:hover svg {
    opacity: 1;
